19	/// The app context, with specialized behavior for the given entity.
20	pub struct Context<'a, T> {
21	    app: &'a mut App,
22	    entity_state: WeakEntity<T>,
23	}
24	
25	impl<'a, T> ops::Deref for Context<'a, T> {
26	    type Target = App;
27	
28	    fn deref(&self) -> &Self::Target {
29	        self.app
30	    }
31	}
32	
33	impl<'a, T> ops::DerefMut for Context<'a, T> {
34	    fn deref_mut(&mut self) -> &mut Self::Target {
35	        self.app
36	    }
37	}
