36	impl AppContext for AsyncApp {
37	    fn new<T: 'static>(&mut self, build_entity: impl FnOnce(&mut Context<T>) -> T) -> Entity<T> {
38	        let app = self.app();
39	        let mut app = app.borrow_mut();
40	        app.new(build_entity)
41	    }
