#![cfg_attr(target_family = "wasm", no_main)]

use gpui::{App, Context, Entity, EventEmitter, prelude::*};
use gpui_platform::application;

/// 实体 A：持有状态，变化时 notify，并可 emit 一个带载荷的事件
struct Producer {
    value: usize,
}

struct ValueChanged {
    new_value: usize,
}

impl EventEmitter<ValueChanged> for Producer {}

/// 实体 B：同时注册 observe 与 subscribe
struct Consumer {
    last_seen: usize,
    received_events: usize,
}

fn run_example() {
    application().run(|cx: &mut App| {
        let producer = cx.new(|_cx| Producer { value: 0 });

        let consumer = cx.new(|cx: &mut Context<Consumer>| {
            cx.observe(&producer, |this, producer, _cx| {
                println!("[observe]  producer 通知了，当前 value = {}", producer.read(_cx).value);
                this.last_seen = producer.read(_cx).value;
            })
            .detach();

            cx.subscribe(&producer, |this, _emitter, event: &ValueChanged, _cx| {
                println!("[subscribe] 收到 ValueChanged 事件，载荷 = {}", event.new_value);
                this.received_events += 1;
            })
            .detach();

            Consumer { last_seen: 0, received_events: 0 }
        });

        // 第一次：只 notify，不 emit
        producer.update(cx, |producer, cx| {
            producer.value += 1;
            cx.notify();
        });

        // 第二次：只 emit，不 notify
        producer.update(cx, |producer, cx| {
            producer.value += 1;
            cx.emit(ValueChanged { new_value: producer.value });
        });

        // 第三次：两者都做
        producer.update(cx, |producer, cx| {
            producer.value += 1;
            cx.notify();
            cx.emit(ValueChanged { new_value: producer.value });
        });

        let consumer = consumer.read(cx);
        println!("最终：last_seen = {}, received_events = {}", consumer.last_seen, consumer.received_events);

        cx.quit();
    });
}

#[cfg(not(target_family = "wasm"))]
fn main() {
    run_example();
}

#[cfg(target_family = "wasm")]
#[wasm_bindgen::prelude::wasm_bindgen(start)]
pub fn start() {
    gpui_platform::web_init();
    run_example();
}
